// How much history one summary covers. `Day` is the default the chart opens on.
export type ContextWindow = "day" | "week" | 
// The whole retained history (`bhippi_core::RETAINED_SAMPLES`).
"all";

export type ConversationMeta = {
	id: string,
	project_path: string,
	title: string,
	created_at: string,
	turn_count: number,
	// Set when this chat was spawned by a team-lead conversation.
	parent_id?: string | null,
	// Worker role (`world`, `gdscript`, `art`, …). Empty for a lead or a normal chat.
	role?: string | null,
};

export type ConversationView = {
	meta: ConversationMeta,
	turns: ChatTurnView[],
};

// How much of its subject an inspector actually saw.
export type Coverage = 
// It was not asked to run.
{ state: "not_scanned" } | 
// It ran and read `items` things.
{ state: "scanned"; items: number } | 
// It ran but the scan caps stopped it early.
{ state: "partial"; items: number; reason: string } | 
/**
 *  It cannot answer from files alone and no measurement exists. `how` is the one
 *  action that would produce one.
 */
{ state: "not_measured"; how: string };

// One provider's slice of one day, for the chart's per-provider series.
export type DayProviderPoint = {
	id: string,
	total_tokens: number,
	cost_usd: number,
};

/**
 *  Whether this turn must follow the Bhippi Design System.
 * 
 *  A flag rather than a persistent setting, and on the turn rather than in config, for the
 *  same reason `Effort` is: it changes what one answer should be, and the user decides that
 *  per question. Someone asking "why is this failing" does not want a design brief in the
 *  reply; someone asking for a settings page does.
 */
export type DesignMode = 
// Answer normally.
"off" | 
// Hold every interface decision to `docs/DESIGN-SYSTEM.md`.
"on";

export type DiffHunk = {
	old_start: number,
	old_lines: number,
	new_start: number,
	new_lines: number,
	header: string,
	lines: DiffLine[],
};

export type DiffLine = {
	line_type: DiffLineType,
	old_line_num: number | null,
	new_line_num: number | null,
	content: string,
};

export type DiffLineType = "added" | "deleted" | "context";

// One row of the health panel.
export type Dimension = {
	inspector: InspectorId,
	label: string,
	coverage: Coverage,
	findings: number,
	// `None` exactly when [`Coverage::scores`] is false.
	score: number | null,
};

/**
 *  Response effort, shown as the composer's speed control (Faster ↔ Smarter).
 * 
 *  Every level changes three real knobs — token ceiling, temperature, and one system
 *  directive — so the choice is visible in the answer, not decorative.
 */
export type Effort = "fast" | "medium" | "balanced" | "extra" | "quality" | "ultra";

// Which Godot surface a window is.
export type EmbedSurface = 
// The Godot editor on the project — the workspace.
"workspace" | 
// The running game. Sits on top of the workspace while it runs.
"game";

// One Godot window the viewport owns, as the page sees it.
export type EmbeddedWindow = {
	surface: EmbedSurface,
	project: string,
	// `0` until the process has been spawned.
	process_id: number,
	// `0` until the window has been found and adopted.
	hwnd: number,
	// `true` once the window is a child of Bhippi's window.
	attached: boolean,
};

/**
 *  What Settings → About says about the engine Bhippi runs.
 * 
 *  Godot is MIT licensed, which is what lets Bhippi ship it; the licence's one condition is
 *  that the notice travels with the binary. This carries the notice to the surface that shows
 *  it, so the obligation is met by the app rather than by a file nobody opens.
 */
export type EngineCredit = {
	// `4.7.1`, or `None` when no engine could be detected at all.
	version: string | null,
	// Where this engine came from, in the words Settings already uses.
	source: string,
	// True when it is the copy Bhippi shipped rather than one found on the machine.
	bundled: boolean,
	// The full notice text — MIT, third-party components, trademarks.
	notice: string,
};

export type EntityId = string;

/**
 *  One citation: something the inspector actually read, and where it read it.
 * 
 *  Evidence is what makes an answer checkable (§21). `source` is an address a person can
 *  open; `claim` is the fact that address supports. Neither may be a paraphrase of the
 *  finding's own title — that is a restatement, not evidence.
 */
export type Evidence = {
	claim: string,
	// `scenes/main.tscn#Door/Area3D`, `scripts/door.gd:42`, `project.godot#input`.
	source: string,
};

// Where the run ended up, whatever the frames showed.
export type EvidenceFinalState = {
	/**
	 *  True only when the probe wrote its `done` line — the one proof the game shut down
	 *  rather than being killed mid-frame.
	 */
	done: boolean,
	sample_count: number,
	last_positions: { [key in string]: number[] },
	vars: { [key in string]: "Null" | ({ Bool: boolean }) & { Array?: never; Number?: never; Object?: never; String?: never } | ({ Number: ({ f64: number }) & { i64?: never; u64?: never } | ({ i64: number }) & { f64?: never; u64?: never } | ({ u64: number }) & { f64?: never; i64?: never } }) & { Array?: never; Bool?: never; Object?: never; String?: never } | ({ String: string }) & { Array?: never; Bool?: never; Number?: never; Object?: never } | ({ Array: Value[] }) & { Bool?: never; Number?: never; Object?: never; String?: never } | ({ Object: { [key in string]: Value } }) & { Array?: never; Bool?: never; Number?: never; String?: never } },
	event_names: string[],
	exit_code: number | null,
	timed_out: boolean,
	stopped_reason: VisualStopReason | null,
	elapsed_ms: number,
};

// One frame and what the game thought was true at that moment.
export type EvidenceFrame = {
	step_index: number | null,
	at_ms: number,
	note: string | null,
	// `None` means this frame is **half a pair** and may not promote anything to passed.
	telemetry_sample: EvidenceSample | null,
};

// The telemetry half of one pair, trimmed to what a model can use.
export type EvidenceSample = {
	frame: number,
	// `Time.get_ticks_msec()` at this sample.
	time_ms: number,
	// How far this sample was from the frame. Never more than [`EVIDENCE_PAIR_TOLERANCE_MS`].
	skew_ms: number,
	// Where every node in the `bhippi_track` group was.
	tracked: TrackedNode[],
	// The watched variables as of this sample.
	vars: { [key in string]: "Null" | ({ Bool: boolean }) & { Array?: never; Number?: never; Object?: never; String?: never } | ({ Number: ({ f64: number }) & { i64?: never; u64?: never } | ({ i64: number }) & { f64?: never; u64?: never } | ({ u64: number }) & { f64?: never; i64?: never } }) & { Array?: never; Bool?: never; Object?: never; String?: never } | ({ String: string }) & { Array?: never; Bool?: never; Number?: never; Object?: never } | ({ Array: Value[] }) & { Bool?: never; Number?: never; Object?: never; String?: never } | ({ Object: { [key in string]: Value } }) & { Array?: never; Bool?: never; Number?: never; String?: never } },
	// Events since the previously paired frame — what happened *between* the two pictures.
	events: TelemetryEvent[],
};

// A finished export.
export type ExportResult = {
	output_path: string,
	ok: boolean,
	log_tail: string[],
	/**
	 *  The version this export recorded (GAD-094). `None` when the export failed, or when
	 *  the version list could not be written — an artefact that exists is still an artefact.
	 */
	version_id: string | null,
};

// Status of installed export templates.
export type ExportTemplatesStatus = {
	is_installed: boolean,
	version: string,
	path: string,
	has_web: boolean,
	has_windows: boolean,
	missing_files: string[],
};

// Roughly what is inside, which is what decides where a pack is offered.
export type FabContent = 
// 2D art small enough and square enough to be a HUD icon.
"icons" | 
// Textures and images that are not icons.
"textures" | "models" | "animations" | "unknown";

// One entry in the vault.
export type FabPack = {
	// The vault folder name, which is also its stable id.
	id: string,
	// The listing title from the pack's own metadata, falling back to the folder name.
	title: string,
	// The seller, when the metadata names one. Attribution the credits page needs.
	seller: string,
	// Absolute path to the pack folder.
	root: string,
	usability: FabUsability,
	content: FabContent,
	// Extension to file count, lowercase, without the dot.
	counts: { [key in string]: number },
	// A cover image inside the pack, if it has one.
	thumbnail: string | null,
	/**
	 *  One line saying why the pack is classified as it is. Shown next to it in the picker,
	 *  so an unusable pack explains itself instead of just being greyed out.
	 */
	note: string,
	// True when [`import_icons`] can pull HUD icons out of this pack.
	supplies_icons: boolean,
};

// What Godot can do with a pack.
export type FabUsability = 
// glTF, PNG, JPEG or TGA: Godot imports these as they are.
"direct" | 
// FBX, which Godot 4 imports only when FBX2glTF is installed.
"needs_fbx" | 
// A Unity package Bhippi can open to get at the textures inside.
"needs_unpack" | 
// Unreal-only. Godot reads neither a `.uasset` nor an undownloaded manifest.
"unusable";

/**
 *  The Fab vault as the picker sees it.
 * 
 *  Named apart from `asset_library::AssetLibraryView` on purpose: that one is the user's own
 *  registered folders, which Bhippi reads directly. This one is a vendor cache full of
 *  formats — `.uasset`, `.unitypackage` — that have to be classified before they mean
 *  anything to Godot.
 */
export type FabVaultView = {
	// The folder that was read, or empty when none was found.
	root: string,
	// True when the default Fab vault exists on this machine.
	found: boolean,
	packs: FabPack[],
	// One line for when nothing usable is there, so an empty picker explains itself.
	note: string,
};

export type FileDiff = {
	path: string,
	filename: string,
	directory: string,
	additions: number,
	deletions: number,
	status: string,
	hunks: DiffHunk[],
};

/**
 *  One thing an inspector found, with everything a person needs to judge it.
 * 
 *  `PartialEq` but not `Eq`: a proposed fix can carry a float property, and a float is not
 *  a thing to compare for total equality.
 */
export type Finding = {
	/**
	 *  Stable across scans: the same problem in the same place keeps the same id, so
	 *  "ignored" and "resolved on 10 Sep" survive a rescan (§23).
	 */
	id: string,
	inspector: InspectorId,
	// A stable `BHP-INS-nnn` code. The UI, the tests and a repair turn key on this.
	code: string,
	severity: Severity,
	// 0–100, and never below [`INSPECT_MIN_CONFIDENCE`].
	confidence: number,
	// WHAT: one line, the problem, not the fix.
	title: string,
	// WHERE.
	location: Location,
	/**
	 *  The one line the drawer prints under the title. Computed here so the webview
	 *  formats nothing (R3).
	 */
	where_label: string,
	// WHY it is a problem: the mechanism, in the project's own terms.
	cause: string,
	// WHAT HAPPENS if it is ignored.
	impact: string,
	// WHAT TO DO, in words, whether or not a typed fix exists.
	recommendation: string,
	// The citations behind the claim.
	evidence: Evidence[],
	// A typed, previewable fix. `None` means the repair needs judgement.
	fix?: ProposedFix | null,
	status: FindingStatus,
	// Computed from `location` and `fix`.
	actions: FindingAction[],
};

// What the drawer offers on a finding. Computed from the location, never authored (§16).
export type FindingAction = 
// Open the file at the line.
"open" | 
// Open the scene in the workspace.
"open_scene" | 
// Focus the node in the open scene and frame the camera on it.
"locate" | 
// Reveal the asset in the Assets dock.
"reveal_asset" | 
// Ask the Inspector about this finding, conversationally.
"ask" | 
// Turn the finding into a normal agent task (§18).
"send_to_agent" | 
// Preview a typed fix. Never applies anything on its own.
"fix" | 
// Stop reporting it.
"ignore";

/**
 *  Where a finding stands. `Resolved` is written by the reconcile step when a later scan
 *  no longer sees it; `Ignored` only ever by the user.
 */
export type FindingStatus = "open" | "resolved" | "ignored";

// The card the user reads before anything is written (§17).
export type FixPreview = {
	finding_id: string,
	title: string,
	summary: string,
	risk: FixRisk,
	// One line per action, in order.
	steps: string[],
	files: string[],
	// Hand this back to `inspector_apply_fix`. It is only valid for this exact preview.
	token: string,
};

/**
 *  How dangerous applying a proposed fix is. It decides nothing on its own — every fix
 *  waits for the same explicit approval (INV-096) — but the user deserves to know.
 */
export type FixRisk = 
// One property or one connection, reversible by the engine's own undo.
"low" | 
// Several nodes or a script body.
"medium" | 
// Touches project settings, deletes something, or spans files.
"high";

/**
 *  One Games-screen card, computed entirely inside the project root.
 * 
 *  It exists so the Games screen never does path arithmetic: the workspace file API is
 *  scoped to the *open* project, and a TypeScript join of "project path" and
 *  `.bhippi/poster.png` would be exactly the business logic INV-073 keeps out of the
 *  webview.
 */
export type GameCardInfo = {
	project: string,
	title: string,
	/**
	 *  The poster as a `data:` URL the card can render straight into `<img src>`, or
	 *  `None` when the game has no poster small enough (or of a type safe enough) to show.
	 *  A URL rather than raw base64 because the media type is read from the file and the
	 *  webview must not guess it.
	 */
	poster_data_url: string | null,
	/**
	 *  Whether the folder holds a `project.godot`. The card's status pill reads this
	 *  rather than sniffing for the file itself: the webview never does path arithmetic
	 *  inside a project (INV-073), and `blocked_reason` cannot answer it — a Godot game
	 *  with no engine installed is blocked *and* a Godot project.
	 */
	is_godot_project: boolean,
	version_count: number,
	// RFC 3339 of the newest export recorded on any version.
	last_export: string | null,
	/**
	 *  `None` when Play and Publish may run; otherwise the reason they may not, in words
	 *  the card puts straight into a tooltip.
	 */
	blocked_reason: string | null,
};

// The Game tab's form, as it crosses IPC.
export type GameSettings = {
	// Never empty: falls back to the project's `name` when no title is set.
	title: string,
	description: string,
	tags: string[],
	// Project-relative, forward slashes.
	poster: string | null,
	credits: boolean,
	web_export_dir: string,
};

// One named point in a project's history.
export type GameVersion = {
	// A ULID, so the ids sort the way the versions do.
	id: string,
	label: string,
	// RFC 3339, UTC.
	created_at: string,
	/**
	 *  The latest Godot journal revision when this version was made. Reverting replays
	 *  every row above it.
	 */
	journal_revision: number,
	export?: VersionExport | null,
};

// Git auto-update result after installation.
export type GitUpdateResult = {
	success: boolean,
	message: string,
	previous_commit: string,
	current_commit: string,
};

// Git auto-update status returned to UI.
export type GitUpdateStatus = {
	update_available: boolean,
	current_version: string,
	remote_version: string,
	current_commit: string,
	remote_commit: string,
	branch: string,
	commits_behind: number,
	commit_message: string | null,
	error: string | null,
};

// One edit to a Godot project.
export type GodotAction = 
// Create a new `.tscn` with a single typed root node.
{ kind: "create_scene"; path: string; root_name: string; root_type: string } | 
/**
 *  Delete a `.tscn`. The mirror of [`GodotAction::CreateScene`], and what a rebuild of
 *  a generated scene — a HUD, a menu — needs before it can write the new one.
 */
{ kind: "delete_scene"; path: string } | { kind: "add_node"; scene: string; 
// `"."` is the scene root.
parent: string; name: string; type: string; properties?: ([string, TscnValue])[]; groups?: string[] } | 
// Remove a node and everything under it.
{ kind: "remove_node"; scene: string; path: string } | { kind: "rename_node"; scene: string; path: string; name: string } | { kind: "reparent_node"; scene: string; path: string; new_parent: string } | { kind: "set_property"; scene: string; path: string; property: string; value: TscnValue } | { kind: "remove_property"; scene: string; path: string; property: string } | { kind: "add_to_group"; scene: string; path: string; group: string } | { kind: "attach_script"; scene: string; path: string; script_res_path: string } | 
// Add a node that instances another scene.
{ kind: "instance_scene"; scene: string; parent: string; name: string; scene_res_path: string } | { kind: "connect_signal"; scene: string; from: string; signal: string; to: string; method: string } | 
/**
 *  Write a GDScript file. The batch does **not** compile it; that is `--check-only`,
 *  which is a process and therefore the runner's job.
 */
{ kind: "write_script"; path: string; source: string } | { kind: "delete_script"; path: string } | { kind: "set_main_scene"; res_path: string } | 
/**
 *  `project.godot` `config/name` and, when present, `Bhippi.game.toml` `[game].name`.
 *  The Godot window title (and therefore Play's window attach) is this string.
 */
{ kind: "set_project_name"; name: string } | { kind: "add_autoload"; name: string; res_path: string } | { kind: "add_input_action"; name: string; keycodes: number[]; deadzone?: number | null };

// An ordered batch that succeeds or fails as one.
export type GodotActionBatch = {
	label: string,
	actions: GodotAction[],
};

// What one action did.
export type GodotActionOutcome = {
	index: number,
	ok: boolean,
	message: string,
	hint?: string | null,
	node_path?: string | null,
	/**
	 *  True when the file this action wrote still has to survive `--check-only` before it
	 *  can be trusted. Lowering never runs Godot, so it says so rather than implying it did.
	 */
	needs_check?: boolean,
};

// What one applied batch did.
export type GodotBatchResult = {
	outcomes: GodotActionOutcome[],
	txn_id: string,
	// Project-relative, forward slashes.
	changed_files: string[],
	file_changes?: TurnFileChange[],
	// Scripts this batch wrote and Godot has now parsed.
	needs_check: string[],
	label: string,
	// The journal revision, or `None` when the ledger was unavailable.
	revision: number | null,
};

// Everything the page needs to draw the viewport's chrome around the hole.
export type GodotEmbedState = {
	workspace: EmbeddedWindow | null,
	game: EmbeddedWindow | null,
	// The surface in front: the game while one runs, else the workspace, else nothing.
	front: EmbedSurface | null,
	// Whether the viewport is on screen and unobstructed, as the page last said.
	visible: boolean,
};

// How a run ended.
export type GodotExit = {
	// `None` when the process was killed rather than exiting on its own.
	code: number | null,
	timed_out: boolean,
	duration_ms: number,
};

/**
 *  One thing wrong with the project, as it crosses IPC.
 * 
 *  A mirror of [`gates::Finding`] because the pre-Godot engine has a type of the same name
 *  and the generated bindings are one flat namespace: two `Finding`s would silently become
 *  whichever one specta saw last. The `Godot` prefix is what keeps the two apart in
 *  `ipc.ts`, and it also reads correctly on the UI side, where both still exist.
 */
export type GodotFinding = {
	// A stable `BHP-GD-4xx` code.
	code: string,
	message: string,
	hint: string,
	// The file (or setting) the finding is about, project-relative.
	where_: string,
};

// What the gates found. Blockers stop a release export (INV-074); warnings do not.
export type GodotGateReport = {
	blockers: GodotFinding[],
	warnings: GodotFinding[],
	/**
	 *  Computed here, not in the webview: `blockers.length === 0` is a rule, and rules live
	 *  in Rust (INV-073).
	 */
	passes: boolean,
};

// A usable Godot on this machine.
export type GodotInstall = {
	// The binary to use whenever stdout matters. On Windows this is the `_console` build.
	cli_exe: string,
	// The windowed binary, when the install ships a separate one.
	gui_exe: string | null,
	version: GodotVersion,
	source: GodotInstallSource,
};

// How a candidate binary was found. Ordered by the priority detection walks them in.
export type GodotInstallSource = 
// `BHIPPI_GODOT` — an explicit override always wins.
"env_var" | 
// The path saved in Bhippi's own settings.
"config" | 
/**
 *  The engine shipped inside Bhippi (ADR-0047). Ranked under the two explicit choices
 *  above and over the discovered ones below: a stray Godot of some other version on
 *  `PATH` must not outrank the build Bhippi pinned, scaffolds for and gates against.
 */
"bundled" | 
// Found on `PATH`.
"path" | 
// A well-known install directory for the platform.
"common_dir";

// A batch of engine output. Never one line per event (INV-076).
export type GodotOutput = {
	project: string,
	lines: GodotOutputLine[],
	// Increments once per emitted batch for this project.
	seq: number,
};

// One line of engine output.
export type GodotOutputLine = {
	stream: GodotStream,
	text: string,
};

// A run starting, running or ending.
export type GodotProcessState = {
	project: string,
	kind: GodotRunKind,
	state: GodotRunState,
	// Present only on `exited`.
	exit: GodotExit | null,
};

// What a running Godot process was started for.
export type GodotRunKind = 
// A windowed game.
"run" | 
// A headless deterministic replay.
"playtest" | 
// A windowed run Bhippi watches and plays through Computer Use (ADR-0044).
"visual_playtest" | 
// A headless export.
"export" | 
// The Godot editor itself.
"editor";

// Where a run is in its life.
export type GodotRunState = "starting" | "running" | "exited";

// One applied, journaled batch of Godot file edits.
export type GodotSceneChanged = {
	project: string,
	// The scene the batch touched, when it touched exactly one.
	scene_rel: string | null,
	txn_id: string,
	// `user` | `agent`
	actor: string,
	label: string,
	// Project-relative, forward slashes.
	changed_files: string[],
};

// Everything the pane needs to decide what to show before anything is clicked.
export type GodotStatus = {
	// `None` is the missing-Godot state (GAD-082), not an error.
	install: GodotInstall | null,
	/**
	 *  What the app may offer to install. Always present: the pane shows it in the
	 *  missing-Godot state and in Settings.
	 */
	offer: InstallOffer,
	/**
	 *  Export templates for the detected version. Exporting without them fails with a
	 *  message about presets, which is the wrong thing to send someone looking for.
	 */
	templates_installed: boolean,
	is_godot_project: boolean,
	manifest_main_scene: string | null,
	running: RunningInfo | null,
	preview_url: string | null,
	// How the install was found, in words, for the Settings row.
	install_source: string | null,
};

// Which stream a line came from.
export type GodotStream = "stdout" | "stderr";

// `4.7.1.stable.official.a13da4feb` taken apart.
export type GodotVersion = {
	major: number,
	minor: number,
	patch: number,
	// `stable`, `rc1`, `beta3`, `dev5` …
	status: string,
	// The line `--version` printed, trimmed.
	raw: string,
};

export type Health = { status: "healthy"; latency_ms: number } | { status: "degraded"; reason: string } | { status: "unavailable"; reason: string } | { status: "disabled" };

// The project's health, computed from findings and nothing else.
export type HealthReport = {
	// The mean of the dimensions that actually scanned. `None` when none did.
	score: number | null,
	/**
	 *  True when every inspector scanned. When false the UI must say so beside the score
	 *  — a number over half the project is not the project's health.
	 */
	complete: boolean,
	// The inspectors with no answer, in rail order.
	incomplete: InspectorId[],
	/**
	 *  The sentence the panel prints beside the score when the picture is not complete
	 *  (§10). `None` when every inspector answered. Computed here so the webview does not
	 *  have to decide when a score may be shown without a caveat (R3).
	 */
	incomplete_line: string | null,
	dimensions: Dimension[],
	counts: SeverityCounts,
};

// What one HUD build did, plus what it could not find art for.
export type HudApplyResult = {
	preset: string,
	skin: string,
	// Project-relative files the build wrote.
	files: string[],
	/**
	 *  Icon roles the preset wanted and the project had nothing for. The HUD falls back to
	 *  its captions for these, so it is a note rather than a failure — and it is the exact
	 *  list [`fab_import_icons`] should be asked for next.
	 */
	unresolved_icons: string[],
	// The journal revision the change landed on, when the ledger was available.
	revision: number | null,
	// True when this replaced a HUD the project already had.
	replaced: boolean,
};

// Everything the picker needs in one call.
export type HudLibraryView = {
	presets: HudPresetView[],
	skins: HudSkinView[],
	roles: IconRoleView[],
	default_skin: string,
	max_persistent: number,
	min_font_size: number,
	safe_area_fraction: number,
};

/**
 *  One preset as the picker draws it.
 * 
 *  A view rather than the table itself: the tables are `&'static str` all the way down,
 *  which is right for a `const` and wrong for a wire type.
 */
export type HudPresetView = {
	id: string,
	title: string,
	purpose: string,
	archetypes: string[],
	// The preset's own default skin.
	skin: string,
	widgets: HudWidgetView[],
	/**
	 *  How many of those are always on screen, against [`MAX_PERSISTENT_WIDGETS`]. The
	 *  number the picker shows, because a HUD's budget is the first thing about it.
	 */
	persistent: number,
	// Icon roles this preset would use if the project had art for them.
	icon_roles: string[],
	godot_nodes: string[],
};

// What a project currently has.
export type HudProjectState = {
	// True when the project carries a generated HUD scene.
	installed: boolean,
	// The preset id the installed HUD was built from, when the script still says so.
	preset: string | null,
	// The skin id it was built with.
	skin: string | null,
	// Icon roles this project already has art for.
	icons: { [key in string]: string },
	// True when the main scene carries a HUD instance.
	attached: boolean,
};

/**
 *  One skin as the picker draws it. Colours cross as `#rrggbbaa` so the swatches need no
 *  conversion on the other side.
 */
export type HudSkinView = {
	id: string,
	title: string,
	blurb: string,
	plate: string,
	track: string,
	accent: string,
	warn: string,
	text: string,
	muted: string,
	outline: string,
	radius: number,
	border: number,
	value_size: number,
	label_size: number,
	uppercase: boolean,
};

/**
 *  The nine anchor positions a widget may take. The doctrine assigns meaning to them:
 *  top-left is the player's own state, top-right is session state, the bottom corners are
 *  resources, and the centre belongs to the game.
 */
export type HudSlot = "top_left" | "top_centre" | "top_right" | "mid_left" | "centre" | "mid_right" | "bottom_left" | "bottom_centre" | "bottom_right";

/**
 *  The doctrine's three budget groups. Only [`Persistent`](Self::Persistent) counts against
 *  [`MAX_PERSISTENT_WIDGETS`].
 */
export type HudVisibility = 
// Needed every second. Always on screen.
"persistent" | 
// Needed on change. Appears, holds, fades.
"on_change" | 
// Needed on demand. Hidden until the player asks.
"on_demand";

/**
 *  What a widget *is*. Each kind maps to a fixed recipe of Godot nodes in [`build`], so a
 *  preset never describes a node tree and no tree is ever hand-written.
 */
export type HudWidgetKind = 
// A meter: track, a lagging ghost segment and a fill, with the value beside it.
"bar" | 
// Discrete pips — lives, hearts, shields. Reads at a glance where a number does not.
"segments" | 
// A tabular number with a scale tick on change.
"counter" | 
// A clock or countdown, tabular.
"timer" | 
// A caption and a line of text: the objective, the position, a hint.
"text" | 
// The one persistent centre element: a light shape over a dark outline.
"reticle" | 
// A radial meter drawn with `draw_arc` — stamina, boost, detection.
"ring" | 
// A north strip across the top: cheaper than a minimap and less of an interruption.
"compass" | 
// A top-down chart of registered targets with a fixed categorical legend.
"minimap" | 
// The on-change channel: a plate that appears, holds and fades.
"toast" | 
// A row of ability or inventory slots with cooldown wipes and key glyphs.
"icon_row" | 
// A button. Puzzle games get a reset; nothing else on a HUD is clickable.
"action" | 
// A curved stealth detection arc across top centre with 4 visual stages (calm, alert, visible, danger).
"stealth_arc" | 
// A character, mech or driver portrait badge with level indicator.
"portrait" | 
// A multi-slot equipment or item matrix with stack counts and cooldowns.
"item_grid";

// One widget as the picker draws it.
export type HudWidgetView = {
	name: string,
	kind: HudWidgetKind,
	slot: HudSlot,
	visibility: HudVisibility,
	binding: string,
	max_binding: string,
	caption: string,
	icon: string,
	low_at: number,
};

// The result of importing a pack's icons into a project.
export type IconImport = {
	imported: ImportedIcon[],
	/**
	 *  Roles the pack had nothing for. The HUD falls back to a caption for these, so they
	 *  are reported rather than treated as a failure.
	 */
	unmatched: string[],
	// The licence written into every sidecar.
	license: string,
};

// One icon role as the picker draws it.
export type IconRoleView = {
	id: string,
	title: string,
	keywords: string[],
};

// What one icon import produced.
export type ImportedIcon = {
	// The HUD role this answers, e.g. `heart`.
	role: string,
	// Project-relative path of the written PNG.
	rel_path: string,
	// The `res://` form, which is what the HUD script loads.
	res_path: string,
	// The path it came from inside the pack, recorded in the sidecar.
	source: string,
};

// View of a [`bhippi_memory::IndexResult`] crossing IPC (plain numeric fields).
export type IndexReport = {
	files_scanned: number,
	files_changed: number,
	files_removed: number,
	symbols_counted: number,
	revision: number,
};

// What the user asked to inspect. The webview names a scope; Rust resolves it.
export type InspectRequest = {
	// `"project"` (the default), `"level"`, `"selection"` or `"changes"`.
	scope?: string | null,
	// For `"level"`: the scene, project-relative or `res://`.
	scene?: string | null,
	// For `"selection"`.
	node?: string | null,
	file?: string | null,
	asset?: string | null,
	// For `"changes"`: the files the caller determined changed.
	files?: string[],
	// Empty runs every inspector.
	inspectors?: InspectorId[],
	// `"critical"` or `"high"`.
	min_severity?: Severity | null,
};

// What one inspection was asked to look at.
export type InspectScope = 
// Everything: every scene, script and asset under the project root.
{ kind: "project" } | 
// One scene and what it instances.
{ kind: "level"; scene: string } | 
// One thing the user has selected — a node, a script, an asset.
{ kind: "selection"; scene?: string | null; node?: string | null; file?: string | null; asset?: string | null } | 
/**
 *  Only the files a caller says changed (§26). The caller owns "what changed" — this
 *  crate never runs git.
 */
{ kind: "changes"; files: string[] };

// One complete inspection.
export type InspectionReport = {
	schema: string,
	scope: InspectScope,
	// The project root as the user sees it.
	project: string,
	// RFC 3339, when the scan started.
	started_at: string,
	duration_ms: number,
	// Worst first, then stable. Two scans of an unchanged project produce the same order.
	findings: Finding[],
	health: HealthReport,
	// What a cap cut off, in the inspector's own words. Empty when nothing was cut.
	truncated: string[],
};

// One row of the Inspector rail (§11).
export type InspectorCard = {
	id: InspectorId,
	label: string,
	// One line: what this specialist looks at.
	blurb: string,
};

// Which specialist found it. The rail is this list, in this order.
export type InspectorId = 
// Scenes, nodes, transforms, lighting, cameras, instancing.
"scene" | 
// Scripts: the project's own source, its symbols and its wiring.
"code" | 
// Reachability: can the game actually be played through?
"gameplay" | 
// Files on disk: size, references, duplication, licence, LODs.
"asset" | 
// Measured cost. Never estimated — see [`InspectorId::Performance`] callers.
"performance" | 
// `Control` trees: HUD, menus, spacing, contrast, reachability.
"ui" | 
// `AnimationPlayer`, `AnimationTree`, state machines, blend times.
"animation" | 
// Collision shapes, bodies, layers and masks.
"physics" | 
// Navigation, agents and the decision graphs behind them.
"ai";

// One scan's result, as the drawer draws it.
export type InspectorScanResult = {
	report: InspectionReport,
	// New, returned and resolved since the previous scan of this project.
	changes: Changes,
	// Findings the user has hidden. Not scored, not shown unless asked for.
	ignored: Finding[],
	/**
	 *  True when the ledger could not be read or written; the scan still stands, but
	 *  "resolved on 10 Sep" will not survive a restart. Never silently false.
	 */
	memory_unavailable: boolean,
};

// What the app may *offer*; nothing here fetches anything.
export type InstallOffer = {
	version: string,
	// `{file}` is replaced with an [`InstallTarget::file_name`].
	download_url_template: string,
	// Where the checksums are and what to do with them.
	sha256_note: string,
	// Ready-made URLs, one per platform, so the UI does not template strings itself.
	downloads: ([InstallTarget, string])[],
};

// The platform a download would be for.
export type InstallTarget = "windows" | "mac_os" | "linux";

/**
 *  A key, spelled either the Godot way (`KEY_W`, `KEY_PAGEUP`) or the way `computer.rs` already
 *  spells keys (`w`, `pageup`). Both resolve to the same virtual-key code.
 */
export type KeyName = string;

// How many files of one kind a folder holds.
export type KindCount = {
	kind: ProjectAssetKind,
	label: string,
	count: number,
};

// One remembered finding identity.
export type LedgerEntry = {
	id: string,
	code: string,
	status: FindingStatus,
	// RFC 3339, the first scan that saw it.
	first_seen: string,
	// RFC 3339, the most recent scan that saw it.
	last_seen: string,
	// RFC 3339, when a scan stopped seeing it. Cleared if it comes back.
	resolved_at?: string | null,
};

// One file in a library, as a search result and as an import source.
export type LibraryAsset = {
	// Absolute — the value `<asset_import>` and the Add button hand back.
	path: string,
	// The registered folder it belongs to.
	folder: string,
	// Relative to that folder, forward slashes.
	rel: string,
	name: string,
	kind: ProjectAssetKind,
	kind_label: string,
	size_bytes: number,
	// A sibling sidecar's licence, else the folder's licence file, else nothing.
	licence: string | null,
};

// One registered folder, as the Assets screen lists it.
export type LibraryFolder = {
	// The path as registered.
	path: string,
	// Its last segment, for the chip.
	name: string,
	// False when the folder is gone; the row stays so the user can remove it knowingly.
	exists: boolean,
	file_count: number,
	counts: KindCount[],
	// True when the walk stopped at [`MAX_LIBRARY_FILES`].
	truncated: boolean,
	// What a `LICENSE` file at the root says, when there is one.
	licence: string | null,
};

/**
 *  What Bhippi may do with a model, decided from its Sketchfab licence slug.
 * 
 *  [`LicenceUsage::Unknown`] is the default on purpose: a row that arrived without a ruling — an
 *  older state file, a field a future Bhippi added — is treated as unshippable rather than
 *  as permitted. A permissive default is how an unlicensed asset reaches a build.
 */
export type LicenceUsage = 
// Ships in a Release export. The sidecar names the SPDX licence.
"allowed" | 
/**
 *  May be imported and played with, but the Release gate will block it (INV-074),
 *  and the panel says so on the card before the click, not after.
 */
"unknown" | 
// Refused at import. The licence forbids the use a game makes of it.
"refused";

// Where the account stands against a backend's rolling plan windows.
export type LimitSnapshot = {
	// `allowed`, `allowed_warning`, or `rejected`.
	status: string,
	session_used: number | null,
	session_resets_at: number | null,
	weekly_used: number | null,
	weekly_resets_at: number | null,
};

/**
 *  Where the finding is, in every addressing scheme that might apply to it.
 * 
 *  Every field is optional and at least one must be set — a finding with no location is a
 *  rumour. The combination decides which actions the drawer offers.
 */
export type Location = {
	// Project-relative scene path, forward slashes (`scenes/main.tscn`).
	scene?: string | null,
	// A node path inside `scene` (`Door/Area3D`). Meaningless without `scene`.
	node?: string | null,
	// Project-relative file path for a code or config finding.
	file?: string | null,
	// 1-based line inside `file`.
	line?: number | null,
	// Project-relative asset path.
	asset?: string | null,
	// A named thing that is not a path: a group, an input action, a signal.
	symbol?: string | null,
};

// One model's spend inside the requested window for one provider.
export type ModelUsage = {
	id: string,
	label: string,
	input_tokens: number,
	output_tokens: number,
	total_tokens: number,
	turns: number,
	cost_usd: number,
	/**
	 *  True when `cost_usd` came from this model's own published rate rather than from
	 *  the vendor's default-model price. The panel labels an inexact figure.
	 */
	cost_is_exact: boolean,
	/**
	 *  True when this row came from the vendor CLI's own session files rather than from
	 *  Bhippi's ledger — every Claude Code session on the machine, not the turns this app
	 *  sent (see [`merge_history_models`]).
	 * 
	 *  It exists because the two are **different scopes and must not be added together**.
	 *  `ProviderUsage::total_tokens` is deliberately Bhippi's own ledger, so that machine-wide
	 *  CLI spend can never fill a local token cap
	 *  (`cli_history_does_not_fill_the_local_token_cap`) — which means a history row can be
	 *  larger than the provider total it sits under. Without this flag the only way to notice
	 *  was to compare the numbers, and the drop-up did not, so it drew a 148M model inside a
	 *  2M day and looked broken. The screen groups these separately and says where they came
	 *  from.
	 */
	from_cli_history: boolean,
};

