// A finished playtest.
export type PlaytestResult = {
	report: TelemetryReport,
	exit: GodotExit,
	telemetry_path: string,
	log_tail: string[],
};

// A whole scripted playtest, as it crosses IPC.
export type PlaytestScript = {
	// Sample every *n* frames; `null` uses the probe's default.
	sample_every: number | null,
	steps: PlaytestScriptStep[],
};

/**
 *  One scripted input, as it crosses IPC.
 * 
 *  A mirror of [`PlaytestStep`] rather than the type itself. The engine's version uses
 *  `skip_serializing_if` so the JSON the probe reads carries only the field that applies,
 *  and a *conditionally absent* field has no single TypeScript type — specta refuses to
 *  generate one, correctly. Here both fields are always present and `null` means "not this
 *  kind of step"; [`PlaytestScript::to_inputs`] converts to the shape the probe wants.
 */
export type PlaytestScriptStep = {
	frame: number,
	// An input action name from `project.godot`'s `[input]` section.
	action: string | null,
	// A `KEY_*` name. Exactly one of `action` and `key` may be set.
	key: string | null,
	pressed: boolean,
};

// The one primary button on a card. Also derived.
export type PluginAction = "open" | "install" | "update" | "configure";

// One row of the merged view the Plugins screen renders.
export type PluginMetadata = {
	id: string,
	name: string,
	version: string,
	description: string,
	category: string,
	// A glyph key the screen maps to an icon. An unknown key falls back to a generic one.
	icon: string,
	status: PluginStatus,
	action: PluginAction,
	// The enable toggle. Built-ins toggle too — they just cannot be uninstalled.
	activated: boolean,
	installed: boolean,
	built_in: boolean,
	/**
	 *  `screen:studio`, `workbench:browser`, `panel:brain`, `settings:Usage` … The
	 *  screen maps this to a route; anything it does not recognise opens nothing.
	 */
	target: string | null,
	// The Settings tab this plugin is configured from, when it has one.
	settings_tab: string | null,
	// Unix seconds; 0 for a catalogue entry the user never installed. Drives "Recent".
	installed_at: number,
	window: PluginWindow | null,
};

/**
 *  What the card's badge says. Derived, never stored — a stored badge goes stale the
 *  moment the catalogue moves.
 */
export type PluginStatus = 
// Ships inside the binary. Can be switched off, never removed.
"built_in" | 
// Present and usable.
"installed" | 
// Installed, but the catalogue carries a newer version than the record.
"update_available" | 
// The capability exists but is unusable until its Settings tab is filled in.
"needs_setup" | 
// Shipped early and honestly labelled: not finished yet.
"beta" | 
// In the catalogue, not installed.
"available";

// A window a URL-installed plugin asks for.
export type PluginWindow = {
	title: string,
	width: number,
	height: number,
	url: string,
};

// Which target a generated preset is for.
export type PresetTarget = "web" | "windows";

// A localhost address the in-app browser can try.
export type PreviewTarget = {
	url: string,
	/**
	 *  Where the guess came from — a framework default, plus the project's own dev
	 *  script when it has one. Never an invented address.
	 */
	label: string,
	// True only when a TCP connection to that port actually succeeded just now.
	reachable: boolean,
};

// One row of the Assets tab.
export type ProjectAsset = {
	// Project-relative, forward slashes — always starts `assets/`.
	rel: string,
	// Final path segment.
	name: string,
	// The folder it groups under, e.g. `assets/models`.
	folder: string,
	kind: ProjectAssetKind,
	// Display label for [`Self::kind`], so the webview never keeps a second table.
	kind_label: string,
	size_bytes: number,
	// The licence the sidecar states. `None` renders as `unknown`.
	licence: string | null,
	/**
	 *  One of `procedural`, `bundled`, `external`, `user` — normalised here. `None` when
	 *  there is no readable sidecar, which is *not* the same as "made by the user".
	 */
	provenance: string | null,
};

/**
 *  What a file under `assets/` *is*, decided by extension rather than by which folder
 *  somebody dropped it in: a texture in `assets/models/` is still a texture.
 */
export type ProjectAssetKind = "model" | "texture" | "audio" | "scene" | "material" | "shader" | "other";

// The Assets tab's whole state.
export type ProjectAssetsView = {
	// Sorted by path. Empty for a freshly scaffolded project, and that is the truth.
	assets: ProjectAsset[],
	// The filter chips, in display order, `all` first.
	sources: AssetSourceFacet[],
	// False when the project has no `assets/` directory at all.
	has_assets_dir: boolean,
	// True when the walk stopped at [`MAX_SCANNED_FILES`].
	truncated: boolean,
	/**
	 *  How many of the listed assets have no licence recorded. The release gate blocks on
	 *  these, so the dock names the number rather than making the user count.
	 */
	unlicensed_count: number,
};

// Rules the project owner wrote, plus where they are stored.
export type ProjectRules = {
	// Markdown as typed. Empty when the file does not exist yet.
	text: string,
	// Project-relative location, shown so the file can be edited outside Bhippi too.
	path: string,
	// False before the file has ever been saved.
	exists: boolean,
};

// One `.gd` file, for the Code tab's picker.
export type ProjectScript = {
	// Project-relative, forward slashes.
	rel: string,
	name: string,
	size_bytes: number,
};

export type ProjectSummary = {
	name: string,
	path: string,
	is_git_repository: boolean,
	branch: string | null,
	active: boolean,
	last_opened_at: number,
};

// Which starting point a new project gets.
export type ProjectTemplate = 
/**
 *  A 3D scene with a light and a camera, and a root script.
 * 
 *  The aliases are the names a person — or the agent, in `<create_game>` — would write.
 *  serde's snake_case of `Empty3D` is `empty3_d`, which nobody types on purpose; the
 *  canonical name stays so the generated bindings do not move.
 */
"empty3_d" | 
// A walking, jumping `CharacterBody3D` on a floor.
"third_person3_d" | 
// A `CharacterBody2D` moving in four directions.
"top_down2_d";

export type ProjectTool = "vs_code" | "cursor" | "antigravity" | "explorer";

// A repair, described. Applying it is somebody else's decision.
export type ProposedFix = {
	// One line: what the change is, in the project's terms.
	summary: string,
	risk: FixRisk,
	/**
	 *  The typed actions, in order. The agent never hand-writes a scene file (R8) and
	 *  neither does a fix.
	 */
	actions: GodotAction[],
	// One human line per action, for the preview card.
	steps: string[],
	// Project-relative files the actions would touch, sorted and de-duplicated.
	files: string[],
	/**
	 *  The token [`crate::inspect::fix::fix_token`] derives from the finding and these
	 *  exact actions. An apply that does not carry it is refused.
	 */
	token: string,
};

// A detected provider row for Settings › Providers (subset until S1 probing lands).
export type ProviderInfo = {
	id: string,
	label: string,
	kind: ProviderKind,
	models: string[],
	health: Health,
	// True when detection found only the credential, not a reachable backend.
	offered: boolean,
	detected_at: string,
	// CLI on PATH · server reachable · credential present · demo always.
	installed: boolean,
	// CLI `--version` output, trimmed. Servers/clouds report no version yet.
	version: string | null,
	// User preference — only enabled providers appear in the chat picker.
	enabled: boolean,
	/**
	 *  True when the backend pins a model with its own flag yet names no known list —
	 *  the composer then offers a free-text field rather than guessing vendor ids.
	 */
	accepts_custom_model: boolean,
	// The active TCP port discovered during server detection.
	detected_port?: number | null,
};

export type ProviderInstallProgress = {
	id: string,
	phase: string,
	message: string,
};

export type ProviderKind = "cli" | "cloud_api" | "local_server" | "demo";

// One provider's spend inside the requested window.
export type ProviderUsage = {
	id: string,
	label: string,
	kind: ProviderKind,
	input_tokens: number,
	output_tokens: number,
	total_tokens: number,
	turns: number,
	// Estimated list-price spend in USD. Always `0.0` when `metered` is false.
	cost_usd: number,
	// True when this vendor bills per token, so the dollar figure carries meaning.
	metered: boolean,
	/**
	 *  True when every token in this row was priced at its own model's published rate.
	 *  False means part of the spend fell back to the vendor default and the dollar
	 *  figure is an estimate — which the panel must say out loud.
	 */
	cost_is_exact: boolean,
	/**
	 *  The ceiling for this window, or `None` when the provider is uncapped — the ring
	 *  then renders as an empty track rather than as instantly full.
	 */
	limit_tokens: number | null,
	// `0.0..=1.0` of `limit_tokens` already spent. `0.0` when uncapped.
	fraction: number,
	// True when the provider is enabled and reachable right now.
	available: boolean,
	// `0.0..=1.0` of the window's tokens that ran through this provider.
	share_of_tokens: number,
	/**
	 *  `0.0..=1.0` of the window's estimated cost. Always `0.0` for an unmetered
	 *  backend, which spends tokens but no money.
	 */
	share_of_cost: number,
	/**
	 *  Fixed slot in the chart's categorical palette, by catalogue position — so a
	 *  provider keeps its colour when another one drops out of the window (ADR-0011).
	 */
	color_slot: number,
	/**
	 *  Current account balance in USD. This is populated from the balance field
	 *  in the usage ledger when available.
	 */
	balance_usd: number | null,
	/**
	 *  Signed-in identity and real provider plan windows. A missing weekly value is never
	 *  replaced with Bhippi's local cap.
	 */
	account: AccountUsage | null,
	// Per-model breakdown for this provider in the window.
	models: ModelUsage[],
	/**
	 *  The ceiling nearest to being hit *for this provider* (SPA-003). The composer reads
	 *  the row of the provider it is pointed at, so one exhausted vendor never blocks
	 *  another.
	 */
	spend_limit: SpendLimitView | null,
};

