// A chat conversation with an AI agent.
"ai_chat" | 
/**
 *  A command-line shell tied to the project. Rendered client-side from stored
 *  CLI sessions; the engine only reports `AiChat` rows.
 */
"cli";

// Live state of a workspace session, derived from its last assistant turn.
export type SessionStatus = 
// A turn is queued or actively streaming.
"running" | 
// The agent is blocked on a permission request.
"paused" | 
// The last turn finished cleanly (done or stopped).
"idle" | 
// The last turn ended on a fault.
"failed";

// How bad it is. Ordered worst-first so a sort by severity is a sort by this.
export type Severity = 
// The game is broken or will not build.
"critical" | 
// A player will hit this.
"high" | 
// Worth fixing before release.
"medium" | 
// Worth fixing eventually.
"low" | 
// An improvement, not a defect.
"suggestion" | 
// A fact worth surfacing that is not a problem at all.
"info";

// How many findings of each severity. Every count is a count, not an estimate.
export type SeverityCounts = {
	critical: number,
	high: number,
	medium: number,
	low: number,
	suggestion: number,
	info: number,
	total: number,
};

